use xiom.io;
type StudentRecord {
  name: Str;
  scores: Vec[Int];
}

fn average_score(student: &StudentRecord) -> Int {
  if student.scores.len() == 0 { return 0; };
  let mut sum = 0;
  let mut i = 0;
  while i < student.scores.len() {
    sum += student.scores.get(i).unwrap();
    i += 1;
  };
  sum / student.scores.len()
}

fn letter_grade_from_avg(avg: Int) -> Str {
  if avg >= 90 { return "A"; };
  if avg >= 80 { return "B"; };
  if avg >= 70 { return "C"; };
  if avg >= 60 { return "D"; };
  "F"
}

fn main() -> Int {
  let mut s1 = StudentRecord{ name: "Alex", scores: Vec[Int].new() };
  s1.scores.push(95); s1.scores.push(88); s1.scores.push(92);
  io.println(average_score(&s1).to_str());
  io.println(letter_grade_from_avg(average_score(&s1)));
  return 0;
}
